import{i as e,r as t,s as n,t as r}from"./app-FtcyK8lR.js";var i=JSON.parse(`{"path":"/guide/installation.html","title":"安装部署","lang":"zh-CN","frontmatter":{},"git":{"updatedTime":1775711656000,"contributors":[{"name":"MurphyYi","username":"MurphyYi","email":"zy84338719@hotmail.com","commits":5,"url":"https://github.com/MurphyYi"}],"changelog":[{"hash":"a9d70e07ea35900ed843b132e1aff5e98cbca5e2","time":1775711656000,"email":"zy84338719@hotmail.com","author":"MurphyYi","message":"v4.3.0"},{"hash":"bcd609a29b0c66ea5adb6db8b2eb8764315ef9e1","time":1775666383000,"email":"zy84338719@hotmail.com","author":"MurphyYi","message":"docs: 更新 README 和部署文档，添加 MinIO 存储支持说明"},{"hash":"46a94be73dccfa2afd836e97cca5b5781eccb641","time":1772867174000,"email":"zy84338719@hotmail.com","author":"MurphyYi","message":"fix: 修复文档中所有内部链接使用相对路径"},{"hash":"acf808fd844d46e164aa5b1e98e65abaf9fa76dd","time":1772854092000,"email":"zy84338719@hotmail.com","author":"MurphyYi","message":"docs: 添加完整的 UI配置流程和平台对接文档"},{"hash":"7bdf9909b19472b012c98787da2927a9e56b5336","time":1772852045000,"email":"zy84338719@hotmail.com","author":"MurphyYi","message":"feat: 添加文档站点和部署配置更新"}]},"filePathRelative":"guide/installation.md"}`),a={name:`installation.md`};function o(r,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[e(`<h1 id="安装部署" tabindex="-1"><a class="header-anchor" href="#安装部署">#</a> 安装部署</h1><p>本文档详细介绍虹桥计划的安装和部署步骤。</p><h2 id="📋-前置要求" tabindex="-1"><a class="header-anchor" href="#📋-前置要求">#</a> 📋 前置要求</h2><h3 id="系统要求" tabindex="-1"><a class="header-anchor" href="#系统要求">#</a> 系统要求</h3><ul><li><strong>操作系统</strong>: Linux / macOS / Windows</li><li><strong>内存</strong>: 最低 512MB，推荐 1GB+</li><li><strong>存储</strong>: 最低 100MB，根据资源使用情况而定</li><li><strong>Go 版本</strong>: Go 1.22+（仅开发需要）</li></ul><h3 id="docker-环境-推荐" tabindex="-1"><a class="header-anchor" href="#docker-环境-推荐">#</a> Docker 环境（推荐）</h3><ul><li>Docker 20.10+</li><li>Docker Compose 2.0+</li></ul><h3 id="kubernetes-环境-可选" tabindex="-1"><a class="header-anchor" href="#kubernetes-环境-可选">#</a> Kubernetes 环境（可选）</h3><ul><li>Kubernetes 1.20+</li><li>kubectl 命令行工具</li><li>Helm 3.0+（可选）</li></ul><h2 id="🚀-部署方式" tabindex="-1"><a class="header-anchor" href="#🚀-部署方式">#</a> 🚀 部署方式</h2><h3 id="方式一-docker-compose-推荐" tabindex="-1"><a class="header-anchor" href="#方式一-docker-compose-推荐">#</a> 方式一：Docker Compose（推荐）</h3><p>这是最简单快捷的部署方式，适合大多数场景。</p><h4 id="_1-克隆项目" tabindex="-1"><a class="header-anchor" href="#_1-克隆项目">#</a> 1. 克隆项目</h4><div class="language-bash line-numbers-mode" data-highlighter="prismjs" data-ext="sh"><pre><code class="language-bash"><span class="line"><span class="token function">git</span> clone https://github.com/yi-nology/rainbow_bridge.git</span>
<span class="line"><span class="token builtin class-name">cd</span> rainbow_bridge/deploy</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div></div></div><h4 id="_2-选择数据库配置" tabindex="-1"><a class="header-anchor" href="#_2-选择数据库配置">#</a> 2. 选择数据库配置</h4><p>项目提供多种数据库配置：</p><p><strong>SQLite（默认，最简单）</strong></p><div class="language-bash line-numbers-mode" data-highlighter="prismjs" data-ext="sh"><pre><code class="language-bash"><span class="line"><span class="token builtin class-name">cd</span> docker-compose/sqlite</span>
<span class="line"><span class="token function">docker</span> compose up <span class="token parameter variable">-d</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>MySQL</strong></p><div class="language-bash line-numbers-mode" data-highlighter="prismjs" data-ext="sh"><pre><code class="language-bash"><span class="line"><span class="token builtin class-name">cd</span> docker-compose/mysql</span>
<span class="line"><span class="token function">docker</span> compose up <span class="token parameter variable">-d</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>PostgreSQL + MinIO（推荐生产环境）</strong></p><div class="language-bash line-numbers-mode" data-highlighter="prismjs" data-ext="sh"><pre><code class="language-bash"><span class="line"><span class="token builtin class-name">cd</span> docker-compose/pgsql-minio</span>
<span class="line"><span class="token function">docker</span> compose up <span class="token parameter variable">-d</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div></div></div><p>此方案包含：</p><ul><li>PostgreSQL 16 作为关系型数据库</li><li>MinIO 对象存储用于静态资源</li><li>自动初始化 MinIO 存储桶</li></ul><p>访问地址：</p><ul><li>管理界面：http://localhost:8080/rainbow-bridge</li><li>MinIO 控制台：http://localhost:9001（用户名: minioadmin, 密码: minioadmin123）</li></ul><h4 id="_3-验证部署" tabindex="-1"><a class="header-anchor" href="#_3-验证部署">#</a> 3. 验证部署</h4><div class="language-bash line-numbers-mode" data-highlighter="prismjs" data-ext="sh"><pre><code class="language-bash"><span class="line"><span class="token comment"># 查看容器状态</span></span>
<span class="line"><span class="token function">docker</span> compose <span class="token function">ps</span></span>
<span class="line"></span>
<span class="line"><span class="token comment"># 查看日志</span></span>
<span class="line"><span class="token function">docker</span> compose logs <span class="token parameter variable">-f</span></span>
<span class="line"></span>
<span class="line"><span class="token comment"># 测试健康检查</span></span>
<span class="line"><span class="token function">curl</span> http://localhost:8080/rainbow-bridge/ping</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h4 id="_4-访问管理界面" tabindex="-1"><a class="header-anchor" href="#_4-访问管理界面">#</a> 4. 访问管理界面</h4><p>打开浏览器访问：http://localhost:8080/rainbow-bridge</p><h3 id="方式二-kubernetes-部署" tabindex="-1"><a class="header-anchor" href="#方式二-kubernetes-部署">#</a> 方式二：Kubernetes 部署</h3><p>适合生产环境的大规模部署。</p><h4 id="_1-准备集群" tabindex="-1"><a class="header-anchor" href="#_1-准备集群">#</a> 1. 准备集群</h4><div class="language-bash line-numbers-mode" data-highlighter="prismjs" data-ext="sh"><pre><code class="language-bash"><span class="line"><span class="token comment"># 启动 Minikube（本地测试）</span></span>
<span class="line">minikube start</span>
<span class="line"></span>
<span class="line"><span class="token comment"># 或使用现有 K8s 集群</span></span>
<span class="line">kubectl cluster-info</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h4 id="_2-部署应用" tabindex="-1"><a class="header-anchor" href="#_2-部署应用">#</a> 2. 部署应用</h4><p><strong>Standalone 模式（简单部署）</strong></p><div class="language-bash line-numbers-mode" data-highlighter="prismjs" data-ext="sh"><pre><code class="language-bash"><span class="line"><span class="token builtin class-name">cd</span> deploy/kubernetes/standalone</span>
<span class="line">kubectl apply <span class="token parameter variable">-f</span> configmap.yaml</span>
<span class="line">kubectl apply <span class="token parameter variable">-f</span> deployment.yaml</span>
<span class="line">kubectl apply <span class="token parameter variable">-f</span> service.yaml</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>PostgreSQL + MinIO 模式（完整部署，推荐生产环境）</strong></p><div class="language-bash line-numbers-mode" data-highlighter="prismjs" data-ext="sh"><pre><code class="language-bash"><span class="line"><span class="token builtin class-name">cd</span> deploy/kubernetes/pgsql-minio</span>
<span class="line">./deploy.sh</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div></div></div><p>或使用 kubectl 手动部署：</p><div class="language-bash line-numbers-mode" data-highlighter="prismjs" data-ext="sh"><pre><code class="language-bash"><span class="line"><span class="token builtin class-name">cd</span> deploy/kubernetes/pgsql-minio</span>
<span class="line">kubectl apply <span class="token parameter variable">-f</span> <span class="token builtin class-name">.</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div></div></div><p>此方案包含：</p><ul><li>PostgreSQL 16 作为关系型数据库</li><li>MinIO 对象存储用于静态资源</li><li>自动初始化 MinIO 存储桶的 Job</li><li>Rainbow Bridge 应用（带 initContainer 等待 MinIO 就绪）</li></ul><p>访问地址：</p><ul><li>管理界面：http://localhost:8080/rainbow-bridge（需端口转发）</li><li>MinIO 控制台：http://localhost:9001（需端口转发，用户名: minioadmin, 密码: minioadmin123）</li></ul><h4 id="_3-验证部署-1" tabindex="-1"><a class="header-anchor" href="#_3-验证部署-1">#</a> 3. 验证部署</h4><div class="language-bash line-numbers-mode" data-highlighter="prismjs" data-ext="sh"><pre><code class="language-bash"><span class="line"><span class="token comment"># 查看 Pod 状态</span></span>
<span class="line">kubectl get pods <span class="token parameter variable">-l</span> <span class="token assign-left variable">app</span><span class="token operator">=</span>rainbow-bridge</span>
<span class="line"></span>
<span class="line"><span class="token comment"># 等待 Pod 就绪</span></span>
<span class="line">kubectl <span class="token function">wait</span> <span class="token parameter variable">--for</span><span class="token operator">=</span>condition<span class="token operator">=</span>ready pod <span class="token parameter variable">-l</span> <span class="token assign-left variable">app</span><span class="token operator">=</span>rainbow-bridge-api <span class="token parameter variable">--timeout</span><span class="token operator">=</span>120s</span>
<span class="line"></span>
<span class="line"><span class="token comment"># 端口转发并测试</span></span>
<span class="line">kubectl port-forward svc/rainbow-bridge-service <span class="token number">8080</span>:80</span>
<span class="line"><span class="token function">curl</span> http://localhost:8080/rainbow-bridge/ping</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="方式三-本地运行-开发环境" tabindex="-1"><a class="header-anchor" href="#方式三-本地运行-开发环境">#</a> 方式三：本地运行（开发环境）</h3><p>适合开发和调试。</p><h4 id="_1-克隆项目-1" tabindex="-1"><a class="header-anchor" href="#_1-克隆项目-1">#</a> 1. 克隆项目</h4><div class="language-bash line-numbers-mode" data-highlighter="prismjs" data-ext="sh"><pre><code class="language-bash"><span class="line"><span class="token function">git</span> clone https://github.com/yi-nology/rainbow_bridge.git</span>
<span class="line"><span class="token builtin class-name">cd</span> rainbow_bridge</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div></div></div><h4 id="_2-构建后端" tabindex="-1"><a class="header-anchor" href="#_2-构建后端">#</a> 2. 构建后端</h4><p><strong>生产模式（默认）</strong></p><div class="language-bash line-numbers-mode" data-highlighter="prismjs" data-ext="sh"><pre><code class="language-bash"><span class="line">./build.sh</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p><strong>开发模式（支持热更新）</strong></p><div class="language-bash line-numbers-mode" data-highlighter="prismjs" data-ext="sh"><pre><code class="language-bash"><span class="line"><span class="token assign-left variable">BUILD_MODE</span><span class="token operator">=</span>dev ./build.sh</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><h4 id="_3-构建前端" tabindex="-1"><a class="header-anchor" href="#_3-构建前端">#</a> 3. 构建前端</h4><div class="language-bash line-numbers-mode" data-highlighter="prismjs" data-ext="sh"><pre><code class="language-bash"><span class="line"><span class="token builtin class-name">cd</span> react</span>
<span class="line"><span class="token function">npm</span> <span class="token function">install</span></span>
<span class="line"><span class="token function">npm</span> run build</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h4 id="_4-启动服务" tabindex="-1"><a class="header-anchor" href="#_4-启动服务">#</a> 4. 启动服务</h4><div class="language-bash line-numbers-mode" data-highlighter="prismjs" data-ext="sh"><pre><code class="language-bash"><span class="line"><span class="token comment"># 使用默认配置</span></span>
<span class="line">./output/bin/hertz_service</span>
<span class="line"></span>
<span class="line"><span class="token comment"># 或指定配置文件</span></span>
<span class="line">./output/bin/hertz_service <span class="token parameter variable">--config</span> config.yaml</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h4 id="_5-访问服务" tabindex="-1"><a class="header-anchor" href="#_5-访问服务">#</a> 5. 访问服务</h4><ul><li>管理界面：http://localhost:8080/rainbow-bridge</li><li>API 接口：http://localhost:8080/rainbow-bridge/api/v1</li><li>健康检查：http://localhost:8080/rainbow-bridge/ping</li></ul><h2 id="⚙️-配置说明" tabindex="-1"><a class="header-anchor" href="#⚙️-配置说明">#</a> ⚙️ 配置说明</h2><h3 id="配置文件" tabindex="-1"><a class="header-anchor" href="#配置文件">#</a> 配置文件</h3><p>主配置文件 <code>config.yaml</code> 包含以下关键配置：</p><div class="language-yaml line-numbers-mode" data-highlighter="prismjs" data-ext="yml"><pre><code class="language-yaml"><span class="line"><span class="token key atrule">server</span><span class="token punctuation">:</span></span>
<span class="line">  <span class="token key atrule">address</span><span class="token punctuation">:</span> <span class="token string">&quot;:8080&quot;</span></span>
<span class="line">  <span class="token key atrule">base_path</span><span class="token punctuation">:</span> <span class="token string">&quot;/rainbow-bridge&quot;</span>  <span class="token comment"># 访问前缀</span></span>
<span class="line">  </span>
<span class="line"><span class="token key atrule">database</span><span class="token punctuation">:</span></span>
<span class="line">  <span class="token key atrule">driver</span><span class="token punctuation">:</span> <span class="token string">&quot;postgres&quot;</span>  <span class="token comment"># sqlite, mysql, postgres</span></span>
<span class="line">  <span class="token key atrule">postgres</span><span class="token punctuation">:</span></span>
<span class="line">    <span class="token key atrule">dsn</span><span class="token punctuation">:</span> <span class="token string">&quot;host=postgres user=rainbow_bridge password=rainbow_bridge_pass dbname=rainbow_bridge port=5432 sslmode=disable TimeZone=UTC&quot;</span></span>
<span class="line">  </span>
<span class="line"><span class="token key atrule">storage</span><span class="token punctuation">:</span></span>
<span class="line">  <span class="token key atrule">type</span><span class="token punctuation">:</span> <span class="token string">&quot;minio&quot;</span>  <span class="token comment"># local 或 minio</span></span>
<span class="line">  <span class="token key atrule">minio</span><span class="token punctuation">:</span></span>
<span class="line">    <span class="token key atrule">endpoint</span><span class="token punctuation">:</span> <span class="token string">&quot;minio:9000&quot;</span></span>
<span class="line">    <span class="token key atrule">access_key</span><span class="token punctuation">:</span> <span class="token string">&quot;minioadmin&quot;</span></span>
<span class="line">    <span class="token key atrule">secret_key</span><span class="token punctuation">:</span> <span class="token string">&quot;minioadmin123&quot;</span></span>
<span class="line">    <span class="token key atrule">use_ssl</span><span class="token punctuation">:</span> <span class="token boolean important">false</span></span>
<span class="line">    <span class="token key atrule">bucket</span><span class="token punctuation">:</span> <span class="token string">&quot;rainbow-bridge&quot;</span></span>
<span class="line">    <span class="token key atrule">region</span><span class="token punctuation">:</span> <span class="token string">&quot;us-east-1&quot;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="环境变量" tabindex="-1"><a class="header-anchor" href="#环境变量">#</a> 环境变量</h3><p>可以通过环境变量覆盖配置：</p><div class="language-bash line-numbers-mode" data-highlighter="prismjs" data-ext="sh"><pre><code class="language-bash"><span class="line"><span class="token comment"># 数据库配置</span></span>
<span class="line"><span class="token builtin class-name">export</span> <span class="token assign-left variable">DATABASE_DRIVER</span><span class="token operator">=</span>mysql</span>
<span class="line"><span class="token builtin class-name">export</span> <span class="token assign-left variable">DATABASE_DSN</span><span class="token operator">=</span><span class="token string">&quot;user:pass@tcp(localhost:3306)/rainbow_bridge?charset=utf8mb4&amp;parseTime=True&amp;loc=Local&quot;</span></span>
<span class="line"></span>
<span class="line"><span class="token comment"># 服务地址</span></span>
<span class="line"><span class="token builtin class-name">export</span> <span class="token assign-left variable">SERVER_ADDRESS</span><span class="token operator">=</span><span class="token string">&quot;:80&quot;</span></span>
<span class="line"><span class="token builtin class-name">export</span> <span class="token assign-left variable">SERVER_BASE_PATH</span><span class="token operator">=</span><span class="token string">&quot;/rainbow-bridge&quot;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h2 id="🔧-自定义配置" tabindex="-1"><a class="header-anchor" href="#🔧-自定义配置">#</a> 🔧 自定义配置</h2><h3 id="修改端口" tabindex="-1"><a class="header-anchor" href="#修改端口">#</a> 修改端口</h3><p>编辑 <code>deploy/docker-compose/config.yaml</code>：</p><div class="language-yaml line-numbers-mode" data-highlighter="prismjs" data-ext="yml"><pre><code class="language-yaml"><span class="line"><span class="token key atrule">server</span><span class="token punctuation">:</span></span>
<span class="line">  <span class="token key atrule">address</span><span class="token punctuation">:</span> <span class="token string">&quot;:9090&quot;</span>  <span class="token comment"># 修改为 9090 端口</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div></div></div><p>然后重启服务：</p><div class="language-bash line-numbers-mode" data-highlighter="prismjs" data-ext="sh"><pre><code class="language-bash"><span class="line"><span class="token function">docker</span> compose down</span>
<span class="line"><span class="token function">docker</span> compose up <span class="token parameter variable">-d</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="数据持久化" tabindex="-1"><a class="header-anchor" href="#数据持久化">#</a> 数据持久化</h3><p>Docker Compose 已配置命名卷，数据会自动持久化：</p><div class="language-bash line-numbers-mode" data-highlighter="prismjs" data-ext="sh"><pre><code class="language-bash"><span class="line"><span class="token comment"># 查看数据卷</span></span>
<span class="line"><span class="token function">docker</span> volume <span class="token function">ls</span> <span class="token operator">|</span> <span class="token function">grep</span> rainbow_bridge</span>
<span class="line"></span>
<span class="line"><span class="token comment"># 备份数据</span></span>
<span class="line"><span class="token function">docker</span> run <span class="token parameter variable">--rm</span> <span class="token punctuation">\\</span></span>
<span class="line">  <span class="token parameter variable">-v</span> rainbow_bridge_data:/data <span class="token punctuation">\\</span></span>
<span class="line">  <span class="token parameter variable">-v</span> <span class="token variable"><span class="token variable">$(</span><span class="token builtin class-name">pwd</span><span class="token variable">)</span></span>:/backup <span class="token punctuation">\\</span></span>
<span class="line">  alpine <span class="token function">tar</span> czf /backup/rainbow_bridge_backup.tar.gz /data</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="https-配置" tabindex="-1"><a class="header-anchor" href="#https-配置">#</a> HTTPS 配置</h3><p>使用 Nginx 反向代理实现 HTTPS：</p><div class="language-bash line-numbers-mode" data-highlighter="prismjs" data-ext="sh"><pre><code class="language-bash"><span class="line"><span class="token comment"># 使用提供的 Nginx 配置</span></span>
<span class="line"><span class="token builtin class-name">cd</span> deploy/nginx</span>
<span class="line"><span class="token comment"># 修改 frontend.conf 中的域名和证书配置</span></span>
<span class="line"><span class="token function">docker</span> compose <span class="token parameter variable">-f</span> docker-compose.yaml <span class="token parameter variable">-f</span> docker-compose.nginx.yml up <span class="token parameter variable">-d</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h2 id="🐛-故障排查" tabindex="-1"><a class="header-anchor" href="#🐛-故障排查">#</a> 🐛 故障排查</h2><h3 id="常见问题" tabindex="-1"><a class="header-anchor" href="#常见问题">#</a> 常见问题</h3><h4 id="_1-容器启动失败" tabindex="-1"><a class="header-anchor" href="#_1-容器启动失败">#</a> 1. 容器启动失败</h4><div class="language-bash line-numbers-mode" data-highlighter="prismjs" data-ext="sh"><pre><code class="language-bash"><span class="line"><span class="token comment"># 查看详细日志</span></span>
<span class="line"><span class="token function">docker</span> compose logs api</span>
<span class="line"></span>
<span class="line"><span class="token comment"># 常见原因：</span></span>
<span class="line"><span class="token comment"># - 端口被占用</span></span>
<span class="line"><span class="token comment"># - 数据库初始化失败</span></span>
<span class="line"><span class="token comment"># - 配置文件错误</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h4 id="_2-无法访问管理界面" tabindex="-1"><a class="header-anchor" href="#_2-无法访问管理界面">#</a> 2. 无法访问管理界面</h4><div class="language-bash line-numbers-mode" data-highlighter="prismjs" data-ext="sh"><pre><code class="language-bash"><span class="line"><span class="token comment"># 检查容器状态</span></span>
<span class="line"><span class="token function">docker</span> compose <span class="token function">ps</span></span>
<span class="line"></span>
<span class="line"><span class="token comment"># 检查端口映射</span></span>
<span class="line"><span class="token function">docker</span> compose port api <span class="token number">8080</span></span>
<span class="line"></span>
<span class="line"><span class="token comment"># 测试 API</span></span>
<span class="line"><span class="token function">curl</span> http://localhost:8080/rainbow-bridge/ping</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h4 id="_3-数据库连接失败" tabindex="-1"><a class="header-anchor" href="#_3-数据库连接失败">#</a> 3. 数据库连接失败</h4><div class="language-bash line-numbers-mode" data-highlighter="prismjs" data-ext="sh"><pre><code class="language-bash"><span class="line"><span class="token comment"># MySQL 等待时间不足</span></span>
<span class="line"><span class="token function">sleep</span> <span class="token number">30</span> <span class="token operator">&amp;&amp;</span> <span class="token function">docker</span> compose up <span class="token parameter variable">-d</span></span>
<span class="line"></span>
<span class="line"><span class="token comment"># 检查数据库日志</span></span>
<span class="line"><span class="token function">docker</span> compose logs db</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="获取帮助" tabindex="-1"><a class="header-anchor" href="#获取帮助">#</a> 获取帮助</h3><ul><li>查看 <a href="https://github.com/yi-nology/rainbow_bridge/issues" target="_blank" rel="noopener noreferrer">Issue 列表</a></li><li>阅读 <a href="https://github.com/yi-nology/rainbow_bridge/blob/main/README.md" target="_blank" rel="noopener noreferrer">技术设计文档</a></li><li>参考 <a href="https://github.com/yi-nology/rainbow_bridge/blob/main/TESTING.md" target="_blank" rel="noopener noreferrer">测试指南</a></li></ul><h2 id="📊-部署验证" tabindex="-1"><a class="header-anchor" href="#📊-部署验证">#</a> 📊 部署验证</h2><p>部署完成后，请验证以下功能：</p><ul><li>✅ 健康检查接口响应正常 (<code>/ping</code>)</li><li>✅ 管理界面可以访问</li><li>✅ API 接口正常工作 (<code>/api/v1/version</code>)</li><li>✅ 可以创建环境和渠道</li><li>✅ 可以上传和下载资源</li><li>✅ 容器日志无严重错误</li></ul><h2 id="🔗-下一步" tabindex="-1"><a class="header-anchor" href="#🔗-下一步">#</a> 🔗 下一步</h2><p>完成安装后，请继续学习：</p><ul><li><a href="./quick-start">快速开始</a> - 体验基本功能</li><li><a href="./ui-config/environment">环境管理</a> - 学习环境管理</li><li><a href="./ui-config/channel">渠道管理</a> - 学习渠道管理</li><li><a href="./ui-config/config">配置管理</a> - 学习配置管理</li><li><a href="./integration/frontend">平台对接</a> - 集成到你的项目</li></ul>`,97)]])}var s=r(a,[[`render`,o]]);export{i as _pageData,s as default};